def test_batch_timeout_and_straggler_limit_params():
    class SimpleModule(dspy.Module):
        def forward(self, value: int) -> int:
            return value * 2

    module = SimpleModule()
    examples = [
        dspy.Example(value=1).with_inputs("value"),
        dspy.Example(value=2).with_inputs("value"),
